CREATE OR REPLACE FUNCTION public.fc_character_power(c fc_characters)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
SELECT round((s->>'health')::numeric*.2+(s->>'mana')::numeric*.1+(s->>'attack')::numeric*5+(s->>'defense')::numeric*3+(s->>'speed')::numeric*2) FROM (SELECT public.fc_apply_family_traits(c.id,jsonb_build_object('consciousness_max',(b->>'consciousness_max')::numeric+coalesce((c.expansion_stats->>'consciousness_max')::numeric,0)+coalesce((c.legacy_grade_stats->>'consciousness_max')::numeric,0)+coalesce((e->>'consciousness_max')::numeric,0),'health',((b->>'health')::numeric+coalesce((c.expansion_stats->>'health')::numeric,0)+coalesce((c.legacy_grade_stats->>'health')::numeric,0)+coalesce((e->>'health')::numeric,0))*(1+public.fc_manual_health(c)),'mana',(b->>'mana')::numeric+coalesce((c.expansion_stats->>'mana')::numeric,0)+coalesce((c.legacy_grade_stats->>'mana')::numeric,0)+coalesce((e->>'mana')::numeric,0),'attack',(b->>'attack')::numeric+coalesce((c.expansion_stats->>'attack')::numeric,0)+coalesce((c.legacy_grade_stats->>'attack')::numeric,0)+coalesce((e->>'attack')::numeric,0),'defense',(b->>'defense')::numeric+coalesce((c.expansion_stats->>'defense')::numeric,0)+coalesce((c.legacy_grade_stats->>'defense')::numeric,0)+coalesce((e->>'defense')::numeric,0),'speed',(b->>'speed')::numeric+coalesce((c.expansion_stats->>'speed')::numeric,0)+coalesce((c.legacy_grade_stats->>'speed')::numeric,0)+coalesce((e->>'speed')::numeric,0))) AS s FROM public.fc_base_stats(c.realm_index,c.realm_layer,1)b,public.fc_equipment_stats(c.id)e) q $function$;
